// This code has been fully generated by an AI.
//
// Map setup shared by the activity detail page and the heatmap.

import * as maplibregl from "./vendor/maplibre-gl-6.15.0/maplibre-gl.mjs";
import { buildStyle, basemapVisibility, overlayLayer, STORAGE_KEY, OVERLAY_KEY } from "./map-style.js";

export { maplibregl };

/** Reads the map configuration embedded by the server. */
export function readMapConfig() {
  return JSON.parse(document.getElementById("map-config").textContent);
}

function load(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key)) ?? fallback;
  } catch {
    return fallback;
  }
}

function save(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Storage may be unavailable in the ingress iframe; the choice is then per page view.
  }
}

/**
 * Creates a map in container with the user's last basemap choice and a
 * layer switcher. Resolves once the style is loaded.
 */
export function createMap(container, cfg, options = {}) {
  let basemap = load(STORAGE_KEY, cfg.default);
  if (!cfg.basemaps.some((b) => b.id === basemap)) basemap = cfg.default;
  const overlays = load(OVERLAY_KEY, []).filter((id) => (cfg.overlays ?? []).some((o) => o.id === id));

  const map = new maplibregl.Map({
    container,
    style: buildStyle(cfg, basemap, overlays),
    attributionControl: { compact: true },
    dragRotate: false,
    pitchWithRotate: false,
    ...options,
  });
  map.touchZoomRotate.disableRotation();
  map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");
  map.addControl(new maplibregl.ScaleControl({ unit: "metric" }), "bottom-left");
  map.addControl(new maplibregl.FullscreenControl(), "top-right");
  map.addControl(new LayerSwitcher(cfg, basemap, overlays), "top-left");
  return new Promise((resolve) => map.on("load", () => resolve(map)));
}

class LayerSwitcher {
  constructor(cfg, basemap, overlays) {
    this.cfg = cfg;
    this.basemap = basemap;
    this.overlays = new Set(overlays);
  }

  onAdd(map) {
    this.map = map;
    const el = document.createElement("div");
    el.className = "maplibregl-ctrl maplibregl-ctrl-group layer-switcher";
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.title = "Kartenebenen";
    toggle.setAttribute("aria-label", "Kartenebenen");
    toggle.textContent = "🗺️";
    const panel = document.createElement("form");
    panel.hidden = true;
    toggle.addEventListener("click", () => (panel.hidden = !panel.hidden));

    for (const b of this.cfg.basemaps) {
      panel.append(this.option("radio", "basemap", b, b.id === this.basemap, () => this.selectBasemap(b.id)));
    }
    if (this.cfg.overlays?.length) {
      const sep = document.createElement("hr");
      panel.append(sep);
      for (const o of this.cfg.overlays) {
        panel.append(this.option("checkbox", "overlay", o, this.overlays.has(o.id), (on) => this.toggleOverlay(o.id, on)));
      }
    }
    el.append(toggle, panel);
    this.el = el;
    return el;
  }

  option(type, name, layer, checked, onChange) {
    const label = document.createElement("label");
    const input = document.createElement("input");
    input.type = type;
    input.name = name;
    input.checked = checked;
    input.addEventListener("change", () => onChange(input.checked));
    label.append(input, " ", layer.label);
    return label;
  }

  selectBasemap(id) {
    this.basemap = id;
    for (const [layer, visibility] of basemapVisibility(this.cfg, id)) {
      this.map.setLayoutProperty(layer, "visibility", visibility);
    }
    save(STORAGE_KEY, id);
  }

  toggleOverlay(id, on) {
    on ? this.overlays.add(id) : this.overlays.delete(id);
    this.map.setLayoutProperty(overlayLayer(id), "visibility", on ? "visible" : "none");
    save(OVERLAY_KEY, [...this.overlays]);
  }

  onRemove() {
    this.el.remove();
  }
}
